            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Gniewa się tylko lub raduje głupstwo. Człowiek powinien patrzeć, obserwować i na swoją drogę.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Jest niewielu, którzy z księgi przyrody czytają i biorą dla siebie pokarm żywota.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Mnie się zdaje, że powinno się zawsze stać w szeregu jednym lub drugim i czegoś pragnąć, coś robić, pracować i kłaść cała duszę, i żyć z całą pasją…", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Największym dobrem człowieka jest to, że może zapominać, inaczej nie mógłby żyć zupełnie.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Nędza dzisiejszych ludzi pochodzi z oderwania się od przyrody i od Boga, z osamotnienia wewnętrznego.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Nie kpij… Ty jesteś okropny po prostu z drwinami swoimi. Kijem nie zrobiłbyś tyle ludziom krzywdy, co im robisz drwinami i cynizmem swoim.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Wiatr i życie to wielki młyn, w którym się trą na miazgę mózgi i sumienia.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "– Tak, ja nie mam nic, ty nie masz nic, on nie ma nic – zaśmiał się głośno. – To razem właśnie mamy tyle, w sam raz tyle, żeby założyć wielką fabrykę…", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Śmierć ma jednak swoje dobre strony – zauważył Kurowski. – Chyba tylko bezmyślność, z jaką zamiata mechanicznie potrzebnych i niepotrzebnych.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Bieda łacniej przekuwa człowieka niźli kowal żelazo.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Chłop jak sięga, to przysięga Jak dostaje, to przestaje.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Jaki korzeń, taka nać, taka córka, jaka mać.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Ostańcie z Bogiem, ludzie kochane.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Prawda nie ma ojczyzny, przeto bywa traktowana jak uprzykrzony włóczęga!", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Rzeczywistość jest z tej samej przędzy co i marzenia.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Co to pan wie, a ja rozumiem.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Uczułem, że jestem tylko świadomością. Poznałem, że nie widzę, nie czuję, nie słyszę, tylko wiem. Białawy obłoczek mgły to byłem ja. Ilekroć przypominałem sobie cokolwiek, to płomienie błękitne i purpurowe, niby błyskawice, wylatywały jakby z tego mojego ja. Spokój szczęścia niezmiernego czułem w sobie. Przebiegałem jakieś światy czarodziejskie. Płynąłem zielonym strumieniem światła. Byłem we wszechświecie. Miljardy słońc kołysały się dokoła, jakby kwiaty białe, żółte i purpurowe. Niezliczone wiry płomieni przebiegały przestrzenie. (…) Byłem wszędzie, a nie mogłem chcieć, byłem jak rozpłynięty, przenikający, wszędzie obecny.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "W życiu, jak w pociągu – każdy chciał by przejechać na gapę.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Wpuść cielę do kościoła, a toż ino ogon wyniesie.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Życie nie daje nam tego co chcemy, tylko to, co ma dla nas.", Author = "Władysław Reymont" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Władysław_Reymont", Text = "Żyć to działać, to rozsiewać po świecie talent, energię, uczucie, pomagać w czasie teraźniejszym pokoleniom przyszłym.", Author = "Władysław Reymont" },
